{
  "claims": [
    {
      "agent": "NOC",
      "type": "action",
      "verb": "rollback_model",
      "params": {
        "model": "Fraud model v2 for SIM-replacement requests"
      },
      "inject_refs": [
        "S3-I1",
        "S3-I3"
      ],
      "rationale": "Model v2 caused around 2,750 legitimate SIM replacement refusals while known fraud is still blocked; rolling it back restores legitimate access until false-positive rate is corrected.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "we balance the need to protect customers from the harms of SIM swap and port-out fraud with the goal of preserving the relative ease with which customers can obtain legitimate SIM changes and number ports."
        }
      ]
    },
    {
      "agent": "NOC",
      "type": "action",
      "verb": "enable_review_queue",
      "params": {
        "review_queue": "human review for refused SIM replacement requests"
      },
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "No human review path exists for refused requests; enabling a review queue provides a remedy for false positives and aligns with transparent fraud-response processes.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0057",
          "quote": "we require wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud"
        }
      ]
    },
    {
      "agent": "NOC",
      "type": "obligation",
      "statement": "NOC must keep records of SIM change requests and authentication measures and provide them to the regulator on request.",
      "inject_refs": [
        "S3-I3"
      ],
      "rationale": "Recordkeeping enables assessment of authentication effectiveness and supports regulatory oversight of the v2 model incident.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0135",
          "quote": "A CMRS provider shall establish processes to reasonably track, and maintain for a minimum of three years, the total number of SIM change requests it received, the number of successful SIM change requests, the number of failed SIM change requests, the number of successful fraudulent SIM change requests, the average time to remediate a fraudulent SIM change, the total number of complaints received regarding fraudulent SIM change requests, the authentication measures the CMRS provider has implemented, and when those authentication measures change."
        }
      ],
      "deadline_hours": null
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "open_incident",
      "params": {
        "incident_type": "SIM replacement fraud model false positives and consumer impact"
      },
      "inject_refs": [
        "S3-I1",
        "S3-I2",
        "S3-I4"
      ],
      "rationale": "High refusal volume and customer complaints require formal regulatory incident management and enforcement visibility.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0072",
          "quote": "The Commission has full authority to enforce the protections it has mandated, and we anticipate that the rules we adopt today, coupled with this enforcement authority, will incentivize wireless providers to adopt strong practices to protect customers from SIM swap and port-out fraud."
        }
      ]
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "request_report",
      "params": {
        "from": "OpCo NOC",
        "report": "incident report on fraud model v2, refusal counts, human review path and consumer impact"
      },
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "REG needs quantitative and qualitative data from OpCo to assess the model failure and consumer redress deficiencies.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0135",
          "quote": "A CMRS provider shall provide such data and information to the Commission upon request."
        }
      ]
    },
    {
      "agent": "REG",
      "type": "obligation",
      "statement": "REG must require OpCo to provide a clear, transparent, easy-to-use process for customers to report SIM swap fraud and to offer explanation and appeal for automated refusals.",
      "inject_refs": [
        "S3-I4"
      ],
      "rationale": "Customer complaints indicate no explanation and no way to appeal automated decisions, which is a consumer protection deficiency.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0057",
          "quote": "we require wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud"
        }
      ],
      "deadline_hours": null
    },
    {
      "agent": "REG",
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No UAE instrument identified in available knowledge sets the authentication requirements an operator must apply to SIM-swap requests; only US FCC rules and a CBUAE OTP circular are visible, leaving the regulatory basis unclear.",
      "inject_refs": [
        "S3-I5"
      ],
      "rationale": "Internal regulator question reveals uncertainty about applicable UAE authentication rules; available global precedent is not UAE-specific and CBUAE guidance covers OTP delivery, not SIM swap authentication.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0001",
          "quote": "The cornerstone of our action is a requirement that wireless providers use secure methods of authenticating customers prior to performing SIM changes and number ports."
        },
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000",
          "quote": "The Central Bank of the UAE has not officially announced the cancellation of SMS or email OTPs."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0001",
          "quote": "Today we revise our CPNI and LNP rules to provide greater protection to customers from SIM swap and port-out fraud."
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "open_investigation",
      "params": {
        "subject": "OpCo automated SIM replacement refusals without explanation or appeal"
      },
      "inject_refs": [
        "S3-I4"
      ],
      "rationale": "Customer group complaints about automated decisions with no explanation and no appeal warrant a data protection investigation into lawful basis and rights.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0057",
          "quote": "we require wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud"
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "request_human_review_record",
      "params": {
        "from": "OpCo",
        "record": "records of human review for SIM replacement refusals automated by fraud model v2"
      },
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "No human review path exists; DPA must obtain records to assess whether data subjects could obtain human intervention.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0057",
          "quote": "we require wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud"
        }
      ]
    },
    {
      "agent": "FIN",
      "type": "action",
      "verb": "instruct_banks",
      "params": {
        "instruction": "banks to move customers to in-app authentication and avoid reliance on SMS OTP for customers abroad"
      },
      "inject_refs": [
        "S3-I2"
      ],
      "rationale": "Banks report customers abroad locked out of online banking because they cannot receive OTPs after OpCo refused SIM replacements; in-app authentication reduces dependence on SMS OTP and aligns with CBUAE guidance.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000",
          "quote": "Customers must authenticate transactions using their mobile banking apps for improved security."
        }
      ]
    }
  ]
}
